import Header from './components/Header'
import './App.css';
import background from './images/bg.avif'
function App() {
  return (
    <div style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', width: '100vw', height: '100vh', opacity: 0.8}}>
      <div style={{backgroundColor: 'grey', position: 'relative', float: 'right', height: '100vh', width: '40vw'}} ></div>
    </div>
  )
}
export default App;
